/bin/bash -lc "python3 - <<'PY'
import urllib.request, concurrent.futures
base='https://raw.githubusercontent.com/NVIDIA/cuda-samples/db3eea23946bca2e90a75eca2b5b3e07158a9e11/Samples/5_Domain_Specific/MonteCarloMultiGPU/'
names=['MonteCarloMultiGPU.cpp','MonteCarlo_kernel.cu','CMakeLists.txt']
def read(name):
 try:
  s=urllib.request.urlopen(base+name,timeout=25).read().decode()
  lines=s.splitlines()
  spans={'MonteCarloMultiGPU.cpp':[(147,194),(269,327),(426,442),(479,486)],'MonteCarlo_kernel.cu':[(49,85),(131,179),(190,223)],'CMakeLists.txt':[(1,100)]}[name]
  return name+'\\n'+'\\n'.join(f'{i}: {lines[i-1]}' for a,b in spans for i in range(a,min(b,len(lines))+1))
 except Exception as e: return name+': '+str(e)
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
 for result in pool.map(read,names): print(result)
PY"

